def parse_ini(text):
    """Sections, keys and values of INI text. See TASK.md."""
    sections = {}
    current_section = ""
    last_key = None

    for line_number, raw_line in enumerate(text.split("\n"), 1):
        line = raw_line[:-1] if raw_line.endswith("\r") else raw_line
        stripped = line.strip()

        if not stripped or stripped[0] in ";#":
            continue

        if stripped.startswith("[") and stripped.endswith("]"):
            name = stripped[1:-1].strip()
            if not name:
                raise ValueError(f"line {line_number}: empty section name")
            current_section = name
            sections.setdefault(current_section, {})
            last_key = None
            continue

        if line.startswith((" ", "\t")):
            if last_key is None:
                raise ValueError(f"line {line_number}: continuation without a key")
            sections[current_section][last_key] += "\n" + stripped
            continue

        if "=" in line:
            raw_key, value = line.split("=", 1)
            key = raw_key.strip()
            if not key:
                raise ValueError(f"line {line_number}: empty key")
            key = key.lower()
            if current_section not in sections:
                sections[current_section] = {}
            sections[current_section][key] = value.strip()
            last_key = key
            continue

        raise ValueError(f"line {line_number}: invalid line")

    return sections
